// Verifies the webhook signature (Standard Webhooks), then passes the event on.
// Needs two environment variables on your n8n instance:
//   SIGNATUREAPI_WEBHOOK_SECRET  the signing secret of your SignatureAPI webhook endpoint
//   NODE_FUNCTION_ALLOW_BUILTIN=crypto  so this node can load the crypto module
const crypto = require('crypto');
const secret = $env.SIGNATUREAPI_WEBHOOK_SECRET;
if (!secret) throw new Error('Set the SIGNATUREAPI_WEBHOOK_SECRET environment variable');

const headers = $input.first().json.headers;
const id = headers['webhook-id'];
const timestamp = headers['webhook-timestamp'];
const signatures = headers['webhook-signature'];
if (!id || !timestamp || !signatures) throw new Error('Missing webhook-id, webhook-timestamp or webhook-signature');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) throw new Error('webhook-timestamp is more than 5 minutes from now');

// The signature covers the raw body bytes, so read them, not the parsed JSON.
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const key = Buffer.from(secret.slice(secret.indexOf('_') + 1), 'base64'); // the base64 part after the prefix
const expected = crypto.createHmac('sha256', key).update(`${id}.${timestamp}.`).update(raw).digest();
const valid = signatures.split(' ').some((entry) => {
  const [version, signature] = entry.split(',');
  if (version !== 'v1' || !signature) return false;
  const received = Buffer.from(signature, 'base64');
  return received.length === expected.length && crypto.timingSafeEqual(received, expected);
});
if (!valid) throw new Error('Invalid webhook signature');

return [{ json: { webhook_id: id, event: JSON.parse(raw.toString('utf8')) } }];
